const D=window.DBI_DATA;
const S={page:'overview',bank:'all',metric:'percent',pillar:'all',focus:'OCB',compare:'LP Bank',search:'',level:'all',evidencePage:1,evidenceView:'list',year:'all',reviewState:'all',pdfSource:'all'};
const pages={overview:['Tổng quan','Digital Banking Index','TỔNG QUAN NGHIÊN CỨU','Chuyển đổi số ngân hàng','So sánh 5 ngân hàng qua 140 tiêu chí và 6 trụ cột năng lực số.'],dna:['DNA ngân hàng','Digital DNA','PHÂN TÍCH NĂNG LỰC','Hồ sơ năng lực số','Đi sâu vào từng ngân hàng và so sánh điểm theo 6 trụ cột.'],journey:['Trưởng thành số','Digital Maturity Profile','HỒ SƠ TRƯỞNG THÀNH SỐ','Mức trưởng thành ngân hàng','So sánh 5 ngân hàng theo 6 trụ cột · dữ liệu gộp 2023–2025.'],evidence:['Bằng chứng','Digital Evidence','TRA CỨU & ĐỐI CHIẾU','Điểm số và bằng chứng','Tra cứu 700 bản ghi, mức chấm và nguồn dẫn chứng.'],method:['Phương pháp','Methodology','CÁCH TÍNH CHỈ SỐ','Phương pháp nghiên cứu','Theo dõi cách đi từ dữ liệu công bố đến điểm số và xếp hạng.']};
pages.downloads=['Tải dữ liệu','Research Data','DỮ LIỆU NGHIÊN CỨU','Thư viện dữ liệu','Tải dữ liệu gốc, kết quả chấm điểm, tiêu chí và tài liệu nguồn.'];
const icons={overview:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="13" y="3" width="6" height="6" rx="1"/><rect x="3" y="13" width="6" height="6" rx="1"/><rect x="13" y="13" width="6" height="6" rx="1"/>',dna:'<path d="M5 3c0 8 12 10 12 18M17 3c0 8-12 10-12 18M6 5h10M7 9h8M7 15h8M6 19h10"/>',journey:'<path d="M3 17l5-5 4 3 7-9M14 6h5v5"/>',evidence:'<path d="M5 3h9l4 4v13H5zM14 3v5h4M8 12h7M8 16h5"/>',method:'<path d="M4 4h14v16H4zM8 8h6M8 12h6M8 16h3"/>'};
icons.downloads='<path d="M11 3v12m-4-4 4 4 4-4M4 16v5h14v-5"/>';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>Number(v).toLocaleString('vi-VN',{minimumFractionDigits:d,maximumFractionDigits:d});
const max=()=>S.metric==='percent'?100:5;
const unit=()=>S.metric==='percent'?'%':'/5';
const value=b=>S.pillar==='all'?(S.metric==='percent'?b.score:b.raw):pv(b,Number(S.pillar));
const pv=(b,i)=>S.metric==='percent'?b.pillars[i]:b.rawPillars[i];
const bank=n=>D.banks.find(b=>b.name===n);
const visible=()=>D.banks.filter(b=>S.bank==='all'||b.name===S.bank);
const ranked=()=>[...D.banks].sort((a,b)=>value(b)-value(a)||a.label.localeCompare(b.label));
const rankOf=(b,getScore=value)=>1+D.banks.filter(other=>getScore(other)-getScore(b)>1e-9).length;
const normalizeSearch=text=>String(text).toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
const activeEvidence=()=>D.evidence.filter(e=>(S.bank==='all'||e.bank===S.bank)&&(S.pillar==='all'||e.pillar===Number(S.pillar)));
const scopedStats=b=>{const rows=activeEvidence().filter(e=>e.bank===b.name),zero=rows.filter(e=>e.level===0).length;return {count:rows.length,zero,coverage:(rows.length-zero)/rows.length*100};};
const matrixRows=()=>{const matches=filteredEvidence(),codes=[...new Set(matches.map(e=>e.code))];return codes.map(code=>({code,sample:D.evidence.find(e=>e.code===code),cells:visible().map(b=>D.evidence.find(e=>e.code===code&&e.bank===b.name))}));};
const badge=b=>`<span class="bankmark" style="--bank:${bankAccent(b)}">${b.name==='LP Bank'?'LP':b.name==='SaigonBank'?'SG':b.name==='HDBank'?'HD':b.name==='TPBank'?'TP':'OC'}</span>`;
const bankAccent=b=>({'OCB':'#B8F13C','LP Bank':'#22D3EE','TPBank':'#FFD43B','HDBank':'#FF4F9A','SaigonBank':'#C5A8FF'}[b.name]??b.color);
function countNumber(value,decimals=0){return '<span class="counter-visual" aria-hidden="true" data-count-to="'+value+'" data-count-decimals="'+decimals+'">'+fmt(value,decimals)+'</span><span class="sr-only">'+fmt(value,decimals)+'</span>'; }
const bname=b=>`<span class="bank-name">${badge(b)}${esc(b.label)}</span>`;
const card=(title,desc,body,extra='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2><p>${desc}</p></div>${extra}</div><div class="card-body">${body}</div></section>`;
const opts=(items,current)=>items.map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('');
const bankOpts=(current,all=false)=>opts([...(all?[['all','Tất cả ngân hàng']]:[]),...D.banks.map(b=>[b.name,b.label])],current);
const pOpts=()=>opts([['all','Tất cả trụ cột'],...D.pillars.map((p,i)=>[String(i),p])],S.pillar);
const note=()=>`<p class="hint">Dữ liệu gộp 2023–2025 · Bộ điểm đã được nhóm duyệt</p>`;
function kpi(label,v,sub,tag='',featured=false,icon='↗'){return `<div class="kpi ${featured?'featured':''}"><div class="kpi-label">${label}<span class="kpi-icon">${icon}</span></div><div class="kpi-value">${v}</div><div class="kpi-bottom">${tag?`<span class="tag">${tag}</span>`:''}${sub}</div></div>`;}
function legend(bs){return `<div class="legend">${bs.map(b=>`<span><i class="legend-dot" style="background:${bankAccent(b)}"></i>${esc(b.label)}</span>`).join('')}</div>`;}
function radar(bs){const cx=210,cy=145,r=108;const point=(i,radius)=>[cx+Math.sin(i*Math.PI/3)*radius,cy-Math.cos(i*Math.PI/3)*radius];const points=radius=>Array.from({length:6},(_,i)=>point(i,radius).join(',')).join(' ');return `<svg class="radar" viewBox="0 0 420 295" role="img" aria-label="Biểu đồ radar so sánh 6 trụ cột của ${esc(bs.map(b=>b.label).join(', '))}"><g>${[.2,.4,.6,.8,1].map(f=>`<polygon points="${points(r*f)}" fill="${f===1?'#F4EFFF':'none'}" stroke="#DED0FF" stroke-width="1"/>`).reverse().join('')}${D.pillars.map((p,i)=>{const [x,y]=point(i,r);const [tx,ty]=point(i,r+25);return `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="#DED0FF"/><text x="${tx}" y="${ty+4}" text-anchor="${i===0||i===3?'middle':i<3?'start':'end'}">${p}</text>`;}).join('')}${[.2,.4,.6,.8,1].map(f=>`<text class="scale" x="${cx+5}" y="${cy-r*f+4}">${S.metric==='percent'?f*100:fmt(f*5,0)}</text>`).join('')}${bs.map(b=>`<polygon points="${D.pillars.map((_,i)=>point(i,r*pv(b,i)/max()).join(',')).join(' ')}" fill="${bankAccent(b)}" fill-opacity=".10" stroke="${bankAccent(b)}" stroke-width="2"/>${D.pillars.map((_,i)=>{const [x,y]=point(i,r*pv(b,i)/max());return `<circle cx="${x}" cy="${y}" r="2.7" fill="${bankAccent(b)}"><title>${esc(b.label)} · ${D.pillars[i]}: ${fmt(pv(b,i))}${unit()}</title></circle>`;}).join('')}`).join('')}</g></svg>`;}
function heatmap(bs){const colors=['#F4EFFF','#E9DDFF','#D5C2FF','#BC9CFF','#A275FF','#6C3BFF'];return '<div class="heatmap-scroll"><table class="heatmap"><thead><tr><th>Ngân hàng</th>'+D.pillars.map(p=>'<th>'+p+'</th>').join('')+'</tr></thead><tbody>'+bs.map(b=>'<tr><td>'+esc(b.label)+'</td>'+D.pillars.map((p,i)=>{const v=pv(b,i),color=Math.min(5,Math.floor(v/max()*6));return '<td style="background:'+colors[color]+';color:'+(color>=5?'#fff':'#1B1233')+'"><button data-focus="'+esc(b.name)+'" data-page="dna" title="'+p+': '+fmt(v)+unit()+' — xem DNA">'+fmt(v)+'</button></td>';}).join('')+'</tr>').join('')+'</tbody></table></div><div class="heatmap-legend">Thấp '+colors.map(c=>'<span style="background:'+c+'"></span>').join('')+' Cao · '+unit()+'</div>';}
function gaps(bs){return D.pillars.map((p,i)=>{const sorted=[...bs].sort((a,b)=>pv(b,i)-pv(a,i));return {p,i,gap:pv(sorted[0],i)-pv(sorted.at(-1),i),hi:sorted[0],lo:sorted.at(-1)};}).sort((a,b)=>b.gap-a.gap);}
function overview(){
  const bs=visible(),r=ranked(),show=r.filter(b=>bs.includes(b)),avg=bs.reduce((a,b)=>a+value(b),0)/bs.length,rows=activeEvidence(),coverage=rows.filter(e=>e.level>0).length/rows.length*100;
  const gap=gaps(bs),lead=show[0],comparisons=S.bank==='all'?[r[0],r[1]]:[lead,r.find(b=>b!==lead)],pillarLabel=S.pillar==='all'?'6 trụ cột':D.pillars[Number(S.pillar)],isTotal=S.pillar==='all';
  const kpis='<div class="kpis">'+kpi('ĐIỂM TRUNG BÌNH',fmt(avg,S.metric==='percent'?1:3)+'<small>'+unit()+'</small>','Trung bình '+bs.length+' ngân hàng','',false,'◷')+kpi('BẢN GHI ĐÁNH GIÁ',rows.length+'<small>bản ghi</small>',(isTotal?'140':D.counts[Number(S.pillar)])+' tiêu chí × '+bs.length+' ngân hàng',pillarLabel,false,'▦')+kpi('TỶ LỆ MỨC > 0',fmt(coverage)+'<small>%</small>',rows.filter(e=>e.level>0).length+' / '+rows.length+' bản ghi có mức > 0','',false,'✓')+kpi('PHẠM VI SO SÁNH',bs.length+'<small>ngân hàng</small>','Dữ liệu công bố gộp 2023–2025','6 trụ cột',false,'↗')+'</div>';
  const chart='<svg class="hero-chart" viewBox="0 0 580 195" role="img" aria-label="Điểm của 5 ngân hàng theo '+esc(pillarLabel)+'"><title>So sánh 5 ngân hàng · '+esc(pillarLabel)+' · '+unit()+'</title>'+[0,.25,.5,.75,1].map(f=>'<line x1="'+(110+f*395)+'" x2="'+(110+f*395)+'" y1="12" y2="165" stroke="#ffffff" stroke-opacity=".18"/><text class="axis-label" x="'+(110+f*395)+'" y="188" text-anchor="middle">'+fmt(f*max(),S.metric==='percent'?0:2)+'</text>').join('')+r.map((b,i)=>'<text x="0" y="'+(29+i*31)+'" fill="#fff" font-size="12" font-weight="700">'+esc(b.label)+'</text><rect x="110" y="'+(14+i*31)+'" width="395" height="21" rx="5" fill="#ffffff" fill-opacity=".12"/><rect class="data-bar" style="--bar-delay:'+(i*70)+'ms" x="110" y="'+(14+i*31)+'" width="'+(value(b)/max()*395)+'" height="21" rx="5" fill="'+bankAccent(b)+'"/><text x="570" y="'+(29+i*31)+'" text-anchor="end" fill="#fff" font-size="12" font-weight="800">'+fmt(value(b),S.metric==='percent'?1:3)+'</text>').join('')+'</svg>';
  const stats=scopedStats(lead),leadPillars=lead[S.metric==='percent'?'pillars':'rawPillars'],strongest=leadPillars.indexOf(Math.max(...leadPillars));
  const guide='<div class="guide-banner"><div class="guide-step"><span>1</span><div>Chọn ngân hàng<small>Dùng bộ lọc bên trên</small></div></div><div class="guide-step"><span>2</span><div>Đọc điểm năng lực<small>So sánh qua 6 trụ cột</small></div></div><div class="guide-step"><span>3</span><div>Kiểm tra bằng chứng<small>Đối chiếu từng tiêu chí</small></div></div><span class="guide-cat" aria-hidden="true"><video data-cat-decoration muted loop playsinline preload="auto" aria-hidden="true" tabindex="-1"><source src="assets/stickers/cat-dance.webm" type="video/webm"></video></span></div>';
  const hero='<div class="overview-hero"><section class="score-hero"><div class="score-hero-head"><div><div class="hero-eyebrow">'+(S.bank==='all'?'ĐIỂM GỘP · NHÓM ĐÃ DUYỆT':'HỒ SƠ ĐANG XEM · ĐIỂM GỘP')+'</div><h2 class="hero-bank-name">'+esc(lead.label)+'</h2><div class="hero-bank-meta">'+esc(pillarLabel)+' · 2023–2025</div></div><span class="hero-rank">HẠNG '+rankOf(lead)+' / 5</span></div><div class="hero-score">'+countNumber(value(lead),S.metric==='percent'?1:3)+'<small>'+unit()+'</small></div><div class="hero-chart-caption"><b>Điểm năng lực số</b><span class="chart-scope">So với toàn bộ 5 ngân hàng</span></div>'+chart+'<div class="score-hero-foot">'+(S.metric==='percent'?'Điểm % được quy đổi từ mức đạt của từng tiêu chí.':'Mức đạt trung bình trên thang 0–5.')+'</div></section><section class="insight-card">'+bankVisual(lead)+'<h2>Khám phá hồ sơ '+esc(lead.label)+'</h2><p>Phân tích hồ sơ năng lực số qua '+esc(pillarLabel)+' trong giai đoạn 2023–2025.</p><div class="overview-facts"><div><span>Trụ cột nổi bật</span><b>'+esc(D.pillars[strongest])+' · '+fmt(leadPillars[strongest])+unit()+'</b></div><div><span>Tiêu chí có mức > 0</span><b>'+fmt(stats.coverage)+'% · '+(stats.count-stats.zero)+' / '+stats.count+' bản ghi có mức &gt; 0</b></div></div><p class="profile-review-note">Bộ điểm do nhóm nghiên cứu chấm và phê duyệt.</p><div class="insight-actions"><button class="button" data-focus="'+esc(lead.name)+'" data-page="dna">Xem DNA ngân hàng ↗</button><button class="button" data-evidence-bank="'+esc(lead.name)+'">Đối chiếu bằng chứng</button></div>'+bankPhotoCredit(lead)+'</section></div>';
  const table='<div class="ranking-scroll"><table class="ranking"><thead><tr><th>HẠNG</th><th>NGÂN HÀNG</th><th>'+ (S.metric==='percent'?'ĐIỂM (%)':'ĐIỂM /5')+'</th><th>'+ (S.metric==='percent'&&isTotal?'PHÂN LOẠI':'CÓ MỨC > 0')+'</th><th></th></tr></thead><tbody>'+show.map(b=>{const br=rows.filter(e=>e.bank===b.name),cov=br.filter(e=>e.level>0).length/br.length*100;return '<tr><td><span class="'+(rankOf(b)===1?'rank-first':'rank-num')+'">'+String(rankOf(b)).padStart(2,'0')+'</span></td><td>'+bname(b)+'</td><td><div class="score-cell"><span class="score-bar" style="--bank:'+bankAccent(b)+'"><span style="width:'+value(b)/max()*100+'%"></span></span><span class="number">'+fmt(value(b),S.metric==='percent'?1:3)+'</span></div></td><td><span class="tag">'+(S.metric==='percent'&&isTotal?b.stage:fmt(cov)+'%')+'</span></td><td><button class="rank-link" data-focus="'+esc(b.name)+'" data-page="dna" aria-label="Xem DNA '+esc(b.label)+'">↗</button></td></tr>';}).join('')+'</tbody></table></div><div class="table-note"><span>Hạng trên 5 ngân hàng · đồng điểm, đồng hạng</span><span>Sơ bộ</span></div>';
  const ranking=card('Bảng xếp hạng','Điểm theo '+(S.metric==='percent'?'tỷ lệ hoàn thành':'mức đạt trung bình')+' · '+pillarLabel,table,'<select id="pillar-filter" aria-label="Lọc trụ cột">'+pOpts()+'</select>');
  const ps=comparisons[0][S.metric==='percent'?'pillars':'rawPillars'],best=ps.indexOf(Math.max(...ps));
  const compare=card('So sánh năng lực số','Hồ sơ 6 trụ cột · '+esc(comparisons.map(b=>b.label).join(' và ')),'<div class="radar-wrap">'+radar(comparisons)+'</div>'+legend(comparisons)+'<div class="radar-summary"><span>↗</span><span><b>'+esc(lead.label)+'</b> có điểm cao nhất ở trụ cột <b>'+D.pillars[best]+'</b> trong hồ sơ của ngân hàng.</span></div>','<button class="button" data-focus="'+esc(lead.name)+'" data-page="dna">Xem DNA ↗</button>');
  const largest=Math.max(...gap.map(g=>g.gap),1e-9);
  const gapChart=gap.map(g=>'<div class="gap-row"><span>'+g.p+'</span><div class="gap-track"><span style="width:'+g.gap/largest*100+'%" title="'+esc(g.hi.label)+' − '+esc(g.lo.label)+': '+fmt(g.gap)+unit()+'"></span></div><strong>'+fmt(g.gap)+'</strong></div>').join('');
  return bankMediaTabs(lead)+'<div class="overview-kpis">'+kpis+'</div>'+hero+guide+'<div class="grid-main">'+ranking+compare+'</div><div class="grid-bottom">'+card('Bản đồ năng lực số','So sánh đủ 6 trụ cột · nhấn một ô để xem ngân hàng',heatmap(show),'<span class="tiny-label">6 TRỤ CỘT</span>')+card('Khoảng cách điểm theo trụ cột','Cao nhất − thấp nhất · '+(S.metric==='percent'?'điểm phần trăm':'điểm trên thang 5'),gapChart+'<div class="insight-band"><span>✧</span><span>'+(bs.length>1?'<strong>'+gap[0].p+'</strong> có khoảng cách lớn nhất: '+fmt(gap[0].gap)+' '+(S.metric==='percent'?'điểm %':'điểm')+', giữa '+esc(gap[0].hi.label)+' và '+esc(gap[0].lo.label)+'.':'Chọn tất cả ngân hàng để phân tích khoảng cách giữa các ngân hàng.')+'</span></div>')+'</div>'+note();
}
function groupSummary(b){const groups=new Map();for(const e of D.evidence.filter(e=>e.bank===b.name)){const key=e.pillar+'|'+e.group;if(!groups.has(key))groups.set(key,{pillar:e.pillar,name:e.group,rows:[]});groups.get(key).rows.push(e);}return [...groups.values()].sort((a,b)=>a.pillar-b.pillar).map(g=>({...g,count:g.rows.length,percent:g.rows.reduce((t,e)=>t+e.percent,0)/g.rows.length,raw:g.rows.reduce((t,e)=>t+e.level,0)/g.rows.length}));}
function groupAnalysis(){const b=bank(S.bank==='all'?S.focus:S.bank),groups=groupSummary(b);return card('Điểm theo nhóm tiêu chí',groups.length+' nhóm · trung bình điểm các tiêu chí trong từng nhóm','<div class="evidence-table-wrap"><table class="evidence-table"><thead><tr><th>TRỤ CỘT</th><th>NHÓM TIÊU CHÍ</th><th>SỐ TIÊU CHÍ</th><th>ĐIỂM '+unit()+'</th></tr></thead><tbody>'+groups.map(g=>'<tr><td>'+D.pillars[g.pillar]+'</td><td>'+esc(g.name)+'</td><td>'+g.count+'</td><td class="number">'+fmt(S.metric==='percent'?g.percent:g.raw)+'</td></tr>').join('')+'</tbody></table></div>');}
function dna(){const b=bank(S.bank==='all'?S.focus:S.bank);if(S.compare===b.name)S.compare='none';const other=bank(S.compare),selected=[b,...(other&&other!==b?[other]:[])],ps=b[S.metric==='percent'?'pillars':'rawPillars'];const best=ps.indexOf(Math.max(...ps)),worst=ps.indexOf(Math.min(...ps));return `<div class="detail-select">${D.banks.map(bb=>`<button class="bank-pill ${bb===b?'active':''}" data-focus="${esc(bb.name)}">${badge(bb)}${esc(bb.label)}</button>`).join('')}</div><div class="detail-hero"><div><div class="tiny-label" style="color:#84b39b">DIGITAL DNA · HẠNG #${rankOf(b,bb=>S.metric==='percent'?bb.score:bb.raw)}</div><h2>${esc(b.label)}</h2><p>140 tiêu chí · 6 trụ cột · ${b.count-b.zero} tiêu chí có mức đạt > 0</p></div>${bankVisual(b,true)}<div><div class="big-score">${countNumber(S.metric==='percent'?b.score:b.raw,S.metric==='percent'?1:3)}<small> ${unit()}</small></div><p>${S.metric==='percent'?b.stage:'Mức đạt trung bình'}</p></div></div><div class="grid-main">${card('Hồ sơ 6 trụ cột','So sánh trực tiếp với ngân hàng khác',`<div class="radar-wrap">${radar(selected)}</div>${legend(selected)}`,`<select id="compare" aria-label="Ngân hàng so sánh">${opts([['none','Không so sánh'],...D.banks.filter(bb=>bb!==b).map(bb=>[bb.name,bb.label])],S.compare)}</select>`)}${card('Năng lực theo trụ cột',`Thước đo: ${S.metric==='percent'?'Digital Score (%)':'mức đạt trung bình /5'}`,`<div class="pillar-list">${D.pillars.map((p,i)=>`<div class="pillar-detail"><span>${p}</span><span class="score-bar" style="--bank:${bankAccent(b)}"><span style="width:${ps[i]/max()*100}%"></span></span><span class="number">${fmt(ps[i])}</span></div>`).join('')}</div><div class="insight-band"><span>ⓘ</span><span>Số tiêu chí ở các trụ cột khác nhau. Digital Score sử dụng trọng số bằng nhau cho 6 trụ cột.</span></div>`)}</div><div class="sw-grid"><section class="card sw-card"><h3>↗ TRỤ CỘT MẠNH NHẤT</h3><h2>${D.pillars[best]} <span class="muted">${fmt(ps[best])}${unit()}</span></h2><p>Điểm cao nhất trong hồ sơ của ${esc(b.label)}. ${D.counts[best]} tiêu chí được đánh giá.</p></section><section class="card sw-card"><h3>↘ TRỤ CỘT CẦN QUAN SÁT</h3><h2>${D.pillars[worst]} <span class="muted">${fmt(ps[worst])}${unit()}</span></h2><p>Điểm thấp nhất trong hồ sơ; cần đối chiếu chất lượng và độ đầy đủ của bằng chứng.</p></section></div>${card('Đi sâu vào bằng chứng',`${b.zero} tiêu chí ở mức 0 · ${fmt(b.coverage)}% tiêu chí có mức đạt > 0`,`<p class="hint" style="font-size:13px;margin-bottom:18px">Điểm số phản ánh dữ liệu đã thu thập và cách chấm của nhóm. Xem từng tiêu chí, nội dung bằng chứng và mô tả mức chấm để diễn giải kết quả.</p><button class="button primary" data-evidence-bank="${esc(b.name)}">Xem 140 tiêu chí của ${esc(b.label)} ↗</button>`)}<div style="height:20px"></div>${groupAnalysis()}<div style="height:22px"></div>${note()}`;}
function journey(){return maturityProfile();}
function filteredEvidence(){const q=normalizeSearch(S.search.trim());return D.evidence.filter(e=>(S.bank==='all'||e.bank===S.bank)&&(S.pillar==='all'||e.pillar===Number(S.pillar))&&(S.level==='all'||e.level===Number(S.level))&&(S.pdfSource==='all'||(S.pdfSource==='related'?pdfSourceMatches(e).length>0:pdfSourceMatches(e).length===0))&&(!q||normalizeSearch([e.name,e.code,e.sourceCode,e.text,e.group,e.bank,bank(e.bank).label,pdfSourceSearchText(e)].join(' ')).includes(q)));}
function evidence(){if(S.evidenceView==='annual')return annualEvidence();return `<div class="view-switch" role="group" aria-label="Cách xem bằng chứng"><button class="button ${S.evidenceView==='list'?'primary':''}" data-view="list" aria-pressed="${S.evidenceView==='list'}">Danh sách bằng chứng</button><button class="button ${S.evidenceView==='matrix'?'primary':''}" data-view="matrix" aria-pressed="${S.evidenceView==='matrix'}">So sánh theo tiêu chí</button><button class="button" data-view="annual" aria-pressed="false">Đối chiếu theo năm</button></div>`+`<div class="evidence-controls"><label class="sr-only" for="evidence-search">Tìm tiêu chí hoặc bằng chứng</label><input id="evidence-search" type="search" class="search-field" placeholder="Tìm tiêu chí, mã, từ khóa…" value="${esc(S.search)}"><select id="pillar-filter" aria-label="Trụ cột">${pOpts()}</select><select id="level-filter" aria-label="Mức đạt">${opts([['all','Tất cả mức đạt'],['0','Mức 0 · Chưa đủ bằng chứng'],...Array.from({length:5},(_,i)=>[String(i+1),'Mức '+(i+1)])],S.level)}</select>${pdfSourceControls()}<span class="hint" style="font-size:10px">Nhấn một dòng để xem chi tiết ↗</span></div><section class="card"><div id="evidence-results"></div></section><div style="height:20px"></div>${note()}`;}
function renderEvidenceResults(){if(S.evidenceView==='annual'){renderAnnualResults();return;}if(S.evidenceView==='matrix'){renderEvidenceMatrix();return;}const list=filteredEvidence(),size=15,pages=Math.max(1,Math.ceil(list.length/size));S.evidencePage=Math.min(S.evidencePage,pages);const start=(S.evidencePage-1)*size,shown=list.slice(start,start+size);$('#evidence-results').innerHTML=`${shown.length?`<div class="evidence-table-wrap"><table class="evidence-table"><thead><tr><th>NGÂN HÀNG</th><th>TIÊU CHÍ</th><th>TRỤ CỘT</th><th>MỨC GỘP EXCEL</th><th>BẰNG CHỨNG GỐC</th><th>NGUỒN PDF BỔ SUNG</th><th></th></tr></thead><tbody>${shown.map(e=>`<tr data-id="${D.evidence.indexOf(e)}" tabindex="0" role="button" aria-label="Xem bằng chứng ${esc(e.name)} của ${esc(e.bank)}"><td>${bname(bank(e.bank))}</td><td class="criterion">${esc(e.name)}<small>${esc(e.code)}</small></td><td>${D.pillars[e.pillar]}</td><td><span class="level ${e.level===0?'zero':''}">${e.level===0?'0 · Chưa đủ bằng chứng':'Mức '+e.level}</span></td><td><div class="excerpt">${esc(e.text)}</div></td><td class="pdf-source-cell">${pdfSourceBadge(e)}</td><td>↗</td></tr>`).join('')}</tbody></table></div>`:'<div class="no-results">Không tìm thấy bản ghi phù hợp. Thử đổi từ khóa hoặc bộ lọc.</div>'}<div class="pagination"><span>${list.length?start+1:0}–${Math.min(start+size,list.length)} / ${list.length} bản ghi</span><div><button id="prev" ${S.evidencePage<=1?'disabled':''}>←</button><span>Trang ${S.evidencePage} / ${pages}</span><button id="next" ${S.evidencePage>=pages?'disabled':''}>→</button></div></div>`;$('#prev').onclick=()=>{S.evidencePage--;renderEvidenceResults();};$('#next').onclick=()=>{S.evidencePage++;renderEvidenceResults();};document.querySelectorAll('[data-id]').forEach(el=>{el.onclick=()=>openEvidence(Number(el.dataset.id));el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});}

function renderEvidenceMatrix(){
  const rows=matrixRows(),size=12,pages=Math.max(1,Math.ceil(rows.length/size));S.evidencePage=Math.min(S.evidencePage,pages);
  const start=(S.evidencePage-1)*size,shown=rows.slice(start,start+size),bs=visible();
  $('#evidence-results').innerHTML=(shown.length?'<div class="matrix-note">Mỗi dòng là một tiêu chí. Nhấn mức đạt để xem bằng chứng. Khi lọc mức đạt/từ khóa, dòng được giữ nếu có ít nhất một ngân hàng khớp; các ô còn lại vẫn hiển thị để so sánh.</div><div class="evidence-table-wrap"><table class="evidence-table evidence-matrix"><thead><tr><th>TIÊU CHÍ</th>'+bs.map(b=>'<th>'+esc(b.label)+'</th>').join('')+'</tr></thead><tbody>'+shown.map(row=>'<tr><td class="criterion">'+esc(row.sample.name)+'<small>'+esc(row.code)+' · '+D.pillars[row.sample.pillar]+'</small></td>'+row.cells.map(e=>'<td><button class="matrix-cell level '+(e.level===0?'zero':'')+'" data-evidence-id="'+D.evidence.indexOf(e)+'" aria-label="Xem '+esc(e.bank)+' · '+esc(e.name)+' · mức '+e.level+'">'+(e.level===0?'0 · Chưa đủ căn cứ':'Mức '+e.level)+'</button></td>').join('')+'</tr>').join('')+'</tbody></table></div>':'<div class="no-results">Không tìm thấy tiêu chí phù hợp.</div>')+'<div class="pagination"><span>'+(rows.length?start+1:0)+'–'+Math.min(start+size,rows.length)+' / '+rows.length+' tiêu chí</span><div><button id="prev" '+(S.evidencePage<=1?'disabled':'')+'>←</button><span>Trang '+S.evidencePage+' / '+pages+'</span><button id="next" '+(S.evidencePage>=pages?'disabled':'')+'>→</button></div></div>';
  $('#prev').onclick=()=>{S.evidencePage--;renderEvidenceResults();};$('#next').onclick=()=>{S.evidencePage++;renderEvidenceResults();};
  document.querySelectorAll('[data-evidence-id]').forEach(el=>el.onclick=()=>openEvidence(Number(el.dataset.evidenceId)));
}
function reportLibrary(){return card('Thư viện báo cáo nguồn','Báo cáo thường niên và phát triển bền vững · 2023–2025',''+D.banks.map(b=>'<details class="report-group"><summary>'+esc(b.label)+' <span>'+D.reports.filter(r=>r.bank===b.name).length+' báo cáo</span></summary><div class="report-links">'+D.reports.filter(r=>r.bank===b.name).map(r=>'<a href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer"><span>'+r.year+' · '+esc(r.type)+'</span><span>Tra cứu ↗</span></a>').join('')+'</div></details>').join(''));}
function downloadReview(){reviewedPooledCSV();}
function downloadYears(){annualCSV(R.records);}
function downloadCodes(){csvDownload([['Mã trong Excel','Mã chuẩn theo Word','Tên tiêu chí','Trạng thái ánh xạ'],...D.criteria.map(c=>[c.sourceCode,c.code,c.name,c.verified?'Khớp tên tiêu chí và cấu trúc trong Word':'Cần rà soát'])],'DBI_Anh_xa_ma_tieu_chi.csv');}
function method(){return '<div class="download-actions" style="margin:0 0 22px"><button class="button primary" data-page="downloads">↓ Tải dữ liệu nghiên cứu</button></div>'+policyPanel()+'<div style="height:22px"></div>'+reportLibrary()+'<div style="height:22px"></div>'+`<div class="kpis">${kpi('ĐỐI TƯỢNG','5<small>ngân hàng</small>','TPB · HDB · LPB · OCB · SGB','',true,'◈')}${kpi('BỘ CHỈ SỐ','140<small>tiêu chí</small>','25 nhóm tiêu chí','6 trụ cột',false,'▦')}${kpi('PHẠM VI','2023–25','Bằng chứng gộp giai đoạn','',false,'◷')}${kpi('TRỌNG SỐ','1/6','Mỗi trụ cột có trọng số bằng nhau','',false,'⚖')}</div><div class="method-grid">${card('Từ dữ liệu đến xếp hạng','Quy trình trong dự án nghiên cứu',`${[['Thu thập','Báo cáo thường niên, báo cáo phát triển bền vững và thông tin công bố của 5 ngân hàng trong giai đoạn 2023–2025.'],['Làm sạch & chuẩn hóa','Thống nhất tên ngân hàng, mã tiêu chí, mức đạt và bằng chứng; giữ 140 tiêu chí cho mỗi ngân hàng.'],['Chấm mức đạt','Đối chiếu bằng chứng với mô tả mức 1–5. Mức 0 được giữ theo quy ước của dataset khi chưa đủ bằng chứng.'],['Quy đổi & tổng hợp','Quy đổi mức đạt ra tỷ lệ hoàn thành; tính trung bình từng trụ cột rồi tính Digital Score.'],['Xếp hạng & rà soát','Xếp điểm từ cao xuống thấp trên cùng nhóm 5 ngân hàng. Kết quả được tính từ bộ mức chấm đã được nhóm duyệt.']].map(([t,p],i)=>`<div class="method-step"><span class="step-num">0${i+1}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}`)}${card('Công thức Digital Score','Áp dụng đúng quy tắc của file chấm điểm',`<div class="mapping">${[0,0,25,50,75,100].map((v,i)=>`<div>Mức ${i}<b>${v}%</b></div>`).join('')}</div><div class="method-copy"><p>File dùng <b>cận dưới</b> của khoảng tỷ lệ cho mức 1–4 vì đầu vào chỉ có mức đạt. Đây là quy ước quy đổi của nhóm.</p><div class="formula">Điểm trụ cột = Σ điểm % tiêu chí / số tiêu chí<br>Digital Score = Σ điểm 6 trụ cột / 6</div><p><b>Dữ liệu theo năm:</b> NA có lý do được loại khỏi mẫu số; ô chưa chấm giữ trống. Nếu còn tiêu chí áp dụng chưa chấm hoặc trụ cột không có tiêu chí áp dụng, chưa công bố điểm tổng thể. Điểm gộp 2023–2025 dùng mẫu số cố định, gồm cả mức 0.</p><p>Điểm tổng thể cho mỗi trụ cột trọng số bằng nhau, dù số tiêu chí từng trụ cột khác nhau.</p><p>Thước đo <b>mức đạt trung bình /5</b> lấy trung bình mức đạt của 140 tiêu chí, dùng cho so sánh với AnalysisDataset.xlsx. Thước đo này có thể tạo thứ hạng khác Digital Score.</p><p>Mức 0 và mức 1 cùng quy đổi 0%, nhưng có ý nghĩa khác nhau: mức 0 là thiếu căn cứ; mức 1 có mô tả mức đạt.</p></div>`)}</div><div class="grid-bottom">${card('Cấu trúc bộ chỉ số','6 trụ cột · 140 tiêu chí thành phần',`${D.pillars.map((p,i)=>`<div class="pillar-detail" style="margin-bottom:13px"><span>${p}</span><span class="score-bar" style="width:100%;--bank:#9dbb8d"><span style="width:${D.counts[i]/29*100}%"></span></span><span>${D.counts[i]}</span></div>`).join('')}`)}${card('Nguồn & giới hạn dữ liệu','Tài liệu và phạm vi nghiên cứu',`<div class="source-file">DBI_DigitalScore_theo_tieu_chi.xlsx<small>Nguồn chính · điểm %, xếp hạng và 700 bằng chứng</small></div><div class="source-file">ScoringReview.xlsx<small>Danh mục tiêu chí và thang chấm của nhóm</small></div><div class="source-file">AnalysisDataset.xlsx<small>Đối chiếu tổng mức đạt · dữ liệu gộp, không có điểm năm</small></div><div class="source-file">Bản sao của NHÓM 3 - NGÂN HÀNG SỐ (2).docx<small>Phạm vi nghiên cứu và cấu trúc dashboard</small></div><div class="method-copy"><p>Thang phân loại của file: 0–&lt;25% Khởi động; 25–&lt;50% Bắt đầu; 50–&lt;75% Hình thành; 75–&lt;100% Nâng cao; 100% Dẫn dắt. Dashboard dùng cùng ngưỡng cho từng trụ cột, phân loại trước khi làm tròn.</p><p>Dashboard trình bày bộ điểm đã được nhóm nghiên cứu duyệt. Link nguồn hiển thị theo thông tin có trong file chuyển giao; thông tin trích dẫn bổ sung được quản lý riêng.</p></div>`)}</div>${note()}`;}
function openEvidence(id){const e=D.evidence[id];$('#dialog-content').innerHTML=`<div class="dialog-bank">${bname(bank(e.bank))}</div><div class="eyebrow">${D.pillars[e.pillar]} · ${esc(e.code)}</div><h2>${esc(e.name)}</h2><span class="level ${e.level===0?'zero':''}">${e.level===0?'Mức 0 · Chưa đủ bằng chứng':'Mức '+e.level}</span> <span class="tag">Quy đổi ${e.percent}%</span>${pdfSourceDetails(e)}<h3>Nội dung bằng chứng gốc</h3><p class="detail-text">${esc(e.text)}</p><h3>Mô tả mức đã chấm</h3><p class="detail-text">${esc(e.level>0?(R.rubrics.find(r=>r.code===e.code)?.levels[e.level-1]??e.rubric):e.rubric)}</p><h3>Nguồn dẫn chứng gốc</h3>${e.urls.length?e.urls.map((u,i)=>`<a class="link" href="${esc(u)}" target="_blank" rel="noopener noreferrer">Mở nguồn ${i+1} ↗<br>${esc(u)}</a>`).join(''):'<p class="detail-text">Chưa có đường dẫn nguồn gốc. Tài liệu liên quan được liệt kê phía trên.</p>'}<h3>Trạng thái</h3><p class="detail-text">${esc('Đã được nhóm duyệt')}</p><button class="button" id="copy-evidence">Sao chép bằng chứng</button>`;$('#dialog-content').innerHTML+=pooledReview(e);document.querySelectorAll('[data-open-annual]').forEach(el=>el.onclick=()=>{S.bank=el.dataset.openAnnual;S.search=el.dataset.code;S.evidenceView='annual';S.year='all';S.reviewState='all';S.level='all';S.evidencePage=1;$('#evidence-dialog').close();if(S.page==='evidence')render();else navigate('evidence');});$('#copy-evidence').onclick=async()=>{const text=[bank(e.bank).label,e.name,e.code,'Mức gộp 2023–2025: '+e.level,e.text,...e.urls,'Nguồn PDF bổ sung · Chưa đủ bằng chứng',...pdfSourceMatches(e).map(s=>s.type+' '+s.reportYear+' · trang PDF '+s.page+'\n'+s.url.replace(/#.*$/,'')+'#page='+s.page+'\n'+s.excerpt)].join('\n');try{await navigator.clipboard.writeText(text);toast('Đã sao chép bằng chứng');}catch{toast('Trình duyệt chưa cho phép sao chép; bạn có thể chọn nội dung trực tiếp.');}};$('#evidence-dialog').showModal();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function navigate(page){location.hash=page;}
function setMenu(open){$('.sidebar').classList.toggle('open',open);$('#mobile-menu').setAttribute('aria-expanded',String(open));$('#menu-backdrop').hidden=!open;}
function render(){
  const p=pages[S.page];$('#crumb').textContent=p[0];$('#eyebrow').textContent=p[2];$('#page-title').innerHTML=esc(p[3])+'<span>.</span>';$('#page-subtitle').textContent=S.page==='evidence'&&S.evidenceView==='annual'?'Tra cứu 2.100 bản ghi theo năm, nguồn/trang và kết quả đối chiếu.':S.page==='evidence'?'Tra cứu 700 bản ghi gộp 2023–2025, mức chấm và nguồn dẫn chứng.':p[4];
  $('#navigation').innerHTML=Object.entries(pages).map(([id,p])=>'<a href="#'+id+'" class="nav-item '+(S.page===id?'active':'')+'" '+(S.page===id?'aria-current="page"':'')+'><svg viewBox="0 0 22 24" fill="none" stroke="currentColor" stroke-width="1.5">'+icons[id]+'</svg><span>'+p[0]+'<small>'+p[1]+'</small></span></a>').join('');
  $('#bank-filter').innerHTML=bankOpts(S.bank,true);$('#metric').value=S.metric;
  $('#metric').hidden=['evidence','journey','method','downloads'].includes(S.page);$('#bank-filter').hidden=['method','downloads'].includes(S.page);$('#reset-filters').hidden=['method','downloads'].includes(S.page);$('.toolbar').hidden=S.page==='downloads';$('#export').innerHTML=S.page==='downloads'?'<span>↓</span> Tải bộ hồ sơ':'<span>↓</span> Xuất dữ liệu';
  const bankLabel=S.bank==='all'?'Tất cả 5 ngân hàng':bank(S.bank).label;
  $('#filter-caption').innerHTML=S.page==='downloads'?'Dữ liệu gộp 2023–2025 · Excel / CSV / JSON / PDF':S.page==='method'?'Bộ chỉ số gồm 6 trụ cột · 25 nhóm · 140 tiêu chí':'<span class="caption-dot"></span><b>'+esc(S.page==='dna'?bank(S.bank==='all'?S.focus:S.bank).label:bankLabel)+'</b><span>·</span>'+(S.page==='overview'||S.page==='evidence'?(S.pillar==='all'?'Tất cả 6 trụ cột':D.pillars[Number(S.pillar)]):'Bằng chứng gộp 2023–2025');
  $('#content').innerHTML=({overview,dna,journey,evidence,method,downloads}[S.page])();
  document.querySelectorAll('#navigation a,.brand').forEach(el=>el.onclick=()=>setMenu(false));
  document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{setMenu(false);if(el.dataset.focus){S.focus=el.dataset.focus;S.bank='all';}if(S.page===el.dataset.page)render();else navigate(el.dataset.page);});
  document.querySelectorAll('.bank-pill').forEach(el=>el.onclick=()=>{S.focus=el.dataset.focus;S.bank='all';if(S.compare===S.focus)S.compare='none';render();});
  document.querySelectorAll('[data-evidence-bank]').forEach(el=>el.onclick=()=>{S.bank=el.dataset.evidenceBank;S.pillar='all';S.level='all';S.pdfSource='all';S.search='';S.evidencePage=1;navigate('evidence');});
  const pillar=$('#pillar-filter');if(pillar)pillar.onchange=()=>{S.pillar=pillar.value;S.evidencePage=1;render();};
  const compare=$('#compare');if(compare)compare.onchange=()=>{S.compare=compare.value;render();};
  document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{S.evidenceView=el.dataset.view;S.level='all';S.pdfSource='all';S.evidencePage=1;render();});if(S.page==='evidence'){$('#evidence-search').oninput=e=>{S.search=e.target.value;S.evidencePage=1;renderEvidenceResults();};$('#level-filter').onchange=e=>{S.level=e.target.value;S.evidencePage=1;renderEvidenceResults();};const pdfFilter=$('#pdf-source-filter');if(S.evidenceView!=='annual'&&pdfFilter)pdfFilter.onchange=e=>{S.pdfSource=e.target.value;S.evidencePage=1;renderEvidenceResults();};renderEvidenceResults();}
  bindBankVisuals();bindReview();bindDownloads();if(window.DBI_MOTION)window.DBI_MOTION.refresh();document.title=p[0]+' · Digital Banking Index';
}
function csvDownload(rows,name){const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất dữ liệu CSV theo bộ lọc hiện tại');}
$('#export').onclick=()=>{
  if(S.page==='downloads'){downloadSubmission();}else if(S.page==='evidence'&&S.evidenceView==='annual'){annualCSV(annualRows(),'DBI_Doi_chieu_da_loc.csv');}else if(S.page==='evidence'&&S.evidenceView==='matrix'){const bs=visible();csvDownload([['Mã chuẩn','Tiêu chí','Trụ cột',...bs.map(b=>b.label+' – Mức đạt')],...matrixRows().map(row=>[row.code,row.sample.name,D.pillars[row.sample.pillar],...row.cells.map(e=>e.level)])],'DBI_So_sanh_tieu_chi.csv');}else if(S.page==='evidence'){pooledSourcesCSV(filteredEvidence());}
  else if(S.page==='dna'){const b=bank(S.bank==='all'?S.focus:S.bank);csvDownload([['Ngân hàng','Trụ cột','Số tiêu chí','Điểm (%)','Mức đạt TB /5'],...D.pillars.map((p,i)=>[b.label,p,D.counts[i],b.pillars[i],b.rawPillars[i]])],'DBI_DNA_'+b.label+'.csv');}
  else if(S.page==='journey'){maturityCSV();}
  else if(S.page==='method'){csvDownload([['Trụ cột','Số tiêu chí','Trọng số (%)','Giai đoạn'],...D.pillars.map((p,i)=>[p,D.counts[i],100/6,D.period])],'DBI_Phuong_phap.csv');}
  else{csvDownload([['Ngân hàng','Giai đoạn','Thước đo','Trụ cột','Hạng trong 5 ngân hàng','Điểm','Digital Score (%)','Mức đạt TB /5','Số tiêu chí theo bộ lọc','Mức 0 theo bộ lọc','Tỷ lệ có mức >0 theo bộ lọc (%)'],...ranked().filter(b=>visible().includes(b)).map(b=>[b.label,D.period,S.metric==='percent'?'Digital Score (%)':'Mức đạt TB /5',S.pillar==='all'?'Tổng thể':D.pillars[Number(S.pillar)],rankOf(b),value(b),b.score,b.raw,scopedStats(b).count,scopedStats(b).zero,scopedStats(b).coverage])],'DBI_Xep_hang_2023-2025.csv');}
};
function globalSearch(){
  const query=$('#global-search').value.trim();if(!query){toast('Nhập ngân hàng hoặc tên tiêu chí để tìm kiếm');return;}
  const key=normalizeSearch(query).replace(/\s/g,''),aliases={'TPBank':'TPB','HDBank':'HDB','LP Bank':'LPB','OCB':'OCB','SaigonBank':'SGB'};
  const found=D.banks.find(b=>[b.name,b.label,aliases[b.name]].some(n=>normalizeSearch(n).replace(/\s/g,'')===key));
  S.pillar='all';S.level='all';S.pdfSource='all';S.evidencePage=1;
  if(found){S.bank=found.name;S.focus=found.name;if(S.page==='dna')render();else navigate('dna');}
  else{S.bank='all';S.search=query;S.evidenceView='list';if(S.page==='evidence')render();else navigate('evidence');}
}
$('#global-search-submit').onclick=globalSearch;$('#global-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();globalSearch();}};
$('#bank-filter').onchange=e=>{S.bank=e.target.value;S.evidencePage=1;render();};$('#metric').onchange=e=>{S.metric=e.target.value;render();};$('#close-dialog').onclick=()=>$('#evidence-dialog').close();$('#evidence-dialog').onclick=e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}};$('#help').onclick=()=>navigate('method');$('#mobile-menu').onclick=()=>setMenu(!$('.sidebar').classList.contains('open'));$('#menu-backdrop').onclick=()=>setMenu(false);document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false);});$('#reset-filters').onclick=()=>{S.bank='all';S.pillar='all';S.level='all';S.search='';S.metric='percent';S.year='all';S.reviewState='all';S.pdfSource='all';S.evidencePage=1;render();toast('Đã đặt lại bộ lọc');};window.addEventListener('hashchange',()=>{S.page=Object.hasOwn(pages,location.hash.slice(1))?location.hash.slice(1):'overview';S.pillar='all';setMenu(false);render();window.scrollTo(0,0);});S.page=Object.hasOwn(pages,location.hash.slice(1))?location.hash.slice(1):'overview';render();
